import os
os.makedirs('templates', exist_ok=True)
os.makedirs('static', exist_ok=True)

open('static/style.css','w').write('''*{margin:0;padding:0;box-sizing:border-box;font-family:Arial}body{background:#000;color:#fff;display:flex;height:100vh;overflow:hidden}.sidebar{width:240px;background:#000;padding:10px;display:flex;flex-direction:column;gap:10px}.logo{padding:15px;font-size:22px;font-weight:900}.logo span{color:#ff0000}.nav{background:#121212;border-radius:8px;padding:8px}.nav a{display:flex;gap:15px;padding:10px;color:#b3b3b3;text-decoration:none;font-weight:bold;border-radius:5px}.nav a.active,.nav a:hover{color:#fff;background:#232323}.library{background:#121212;border-radius:8px;flex:1;padding:12px;overflow:auto}.main{flex:1;background:linear-gradient(#1a1a1a,#000);overflow:auto;padding-bottom:90px}.topbar{display:flex;justify-content:space-between;padding:15px 25px;background:rgba(0,0,0,0.5);position:sticky;top:0}.btn{background:#ff0000;color:#fff;padding:8px 20px;border-radius:20px;text-decoration:none;font-weight:bold;border:none}.section{padding:10px 25px}.cards{display:flex;gap:20px;overflow-x:auto;padding:10px 0}.card{background:#181818;padding:12px;border-radius:8px;min-width:170px}.card:hover{background:#282828}.card img{width:100%;height:150px;object-fit:cover;border-radius:6px}.card h4{margin:10px 0 4px;font-size:14px}.card p{color:#b3b3b3;font-size:12px}.song-row{display:flex;align-items:center;gap:15px;padding:8px 10px;border-radius:5px}.song-row:hover{background:#2a2a2a}.song-row img{width:45px;height:45px}.player{position:fixed;bottom:0;left:0;right:0;height:80px;background:#181818;border-top:1px solid #282828;display:flex;align-items:center;justify-content:space-between;padding:0 15px}.search-box{width:350px;padding:12px;background:#242424;border:none;border-radius:20px;color:white}''')

open('templates/login.html','w').write('''<!DOCTYPE html><html><head><title>Login - PLUTO WAVE</title><meta name="viewport" content="width=device-width, initial-scale=1"><style>body{background:#000;color:#fff;font-family:Arial;display:flex;justify-content:center;align-items:center;height:100vh}.box{background:#121212;padding:30px;border-radius:10px;width:350px;text-align:center;border:1px solid #222}input{width:100%;padding:12px;margin:8px 0;background:#242424;border:1px solid #333;color:white;border-radius:5px}.btn{width:100%;background:#ff0000;color:white;padding:12px;border:none;border-radius:25px;font-weight:bold;margin-top:10px}a{color:#ff0000;text-decoration:none}.error{background:#ff000033;color:#ff5555;padding:8px;border-radius:5px;margin:10px 0}</style></head><body><div class="box"><h1>PLUTO <span style="color:#ff0000">WAVE</span></h1><br><h3>Log in</h3>{% if error %}<div class="error">{{error}}</div>{% endif %}<form method="POST"><input type="email" name="email" placeholder="yourname@gmail.com" required><input type="password" name="password" placeholder="Password" required><button class="btn">LOG IN</button></form><p style="margin-top:15px;font-size:14px;color:#b3b3b3">No account? <a href="/signup">Sign up with Gmail</a></p></div></body></html>''')

open('templates/signup.html','w').write('''<!DOCTYPE html><html><head><title>Sign Up - PLUTO WAVE</title><meta name="viewport" content="width=device-width, initial-scale=1"><style>body{background:#000;color:#fff;font-family:Arial;display:flex;justify-content:center;align-items:center;height:100vh}.box{background:#121212;padding:30px;border-radius:10px;width:350px;text-align:center;border:1px solid #222}input{width:100%;padding:12px;margin:8px 0;background:#242424;border:1px solid #333;color:white;border-radius:5px}.btn{width:100%;background:#ff0000;color:white;padding:12px;border:none;border-radius:25px;font-weight:bold;margin-top:10px}a{color:#ff0000;text-decoration:none}.error{background:#ff000033;color:#ff5555;padding:8px;border-radius:5px;margin:10px 0}</style></head><body><div class="box"><h1>PLUTO <span style="color:#ff0000">WAVE</span></h1><br><h3>Sign up with Gmail</h3>{% if error %}<div class="error">{{error}}</div>{% endif %}<form method="POST"><input type="email" name="email" placeholder="yourname@gmail.com" required><input type="password" name="password" placeholder="Create password" required><button class="btn">SIGN UP</button></form><p style="margin-top:15px;font-size:14px;color:#b3b3b3">Have account? <a href="/login">Log in</a></p></div></body></html>''')

open('templates/base.html','w').write('''<!DOCTYPE html><html><head><title>PLUTO WAVE</title><meta name="viewport" content="width=device-width, initial-scale=1.0"><link rel="stylesheet" href="{{ url_for('static', filename='style.css') }}"></head><body><div class="sidebar"><div class="logo">PLUTO <span>WAVE</span></div><div class="nav"><a href="/" class="{{ 'active' if page=='home' }}">Home</a><a href="/search" class="{{ 'active' if page=='search' }}">Search</a><a href="/library" class="{{ 'active' if page=='library' }}">Library</a></div><div class="library"><p style="color:#b3b3b3;font-size:12px">{{user}}</p><br><a href="/upload" style="color:white;text-decoration:none">+ Create</a><br><br><a href="/logout" style="color:#ff5555;text-decoration:none">Log out</a></div></div><div class="main"><div class="topbar"><div></div><a class="btn" href="/upload">Upload</a></div>{% block content %}{% endblock %}</div><div class="player"><div style="display:flex;gap:10px;align-items:center"><div style="width:50px;height:50px;background:#ff0000;border-radius:5px"></div><div><b id="p-title">Pluto Wave</b><br><small style="color:#b3b3b3" id="p-artist">Select song</small></div></div><audio id="mainAudio" controls style="width:300px"></audio></div><script>function playSong(f,t,a){document.getElementById('mainAudio').src='/static/music/'+f;document.getElementById('mainAudio').play();document.getElementById('p-title').innerText=t;document.getElementById('p-artist').innerText=a;}</script></body></html>''')

open('templates/index.html','w').write('''{% extends 'base.html' %}{% block content %}<div class="section"><h2>Good evening</h2><div class="cards">{% for p in playlists %}<div class="card" onclick="location.href='/playlist/{{p.id}}'"><img src="https://via.placeholder.com/150/FF0000/FFFFFF?text={{p.name}}"><h4>{{p.name}}</h4><p>{{p.desc}}</p></div>{% endfor %}</div></div><div class="section"><h2>Popular Artists</h2><div class="cards">{% for a in artists %}<div class="card" onclick="location.href='/artist/{{a.id}}'"><img src="https://via.placeholder.com/150/111/FF0000?text={{a.name}}" style="border-radius:50%"><h4>{{a.name}}</h4><p>Artist</p></div>{% endfor %}</div></div><div class="section"><h2>Trending Now</h2>{% for s in songs %}<div class="song-row" onclick="playSong('{{s.file}}','{{s.title}}','{{s.artist}}')"><img src="https://via.placeholder.com/100"><div><b>{{s.title}}</b><br><small>{{s.artist}}</small></div></div>{% endfor %}</div>{% endblock %}''')

open('templates/search.html','w').write('''{% extends 'base.html' %}{% block content %}<div class="section"><form><input class="search-box" name="q" placeholder="What do you want to play?"></form><br><h3>Browse</h3><div class="cards"><div class="card" style="background:#E13300"><h2>Afrobeat</h2></div><div class="card" style="background:#1E3264"><h2>Hip Hop</h2></div><div class="card" style="background:#8D67AB"><h2>Chill</h2></div></div><h3 style="margin-top:20px">Songs</h3>{% for s in songs %}<div class="song-row" onclick="playSong('{{s.file}}','{{s.title}}','{{s.artist}}')"><img src="https://via.placeholder.com/100"><div><b>{{s.title}}</b><br><small>{{s.artist}}</small></div></div>{% endfor %}</div>{% endblock %}''')

open('templates/library.html','w').write('''{% extends 'base.html' %}{% block content %}<div class="section"><h2>Your Library</h2><div class="cards">{% for p in playlists %}<div class="card"><img src="https://via.placeholder.com/150/FF0000/FFFFFF?text={{p.name}}"><h4>{{p.name}}</h4><p>By Pluto</p></div>{% endfor %}</div><h3 style="margin-top:20px">Liked</h3>{% for s in songs %}<div class="song-row"><img src="https://via.placeholder.com/100"><div><b>{{s.title}}</b><br><small>{{s.artist}}</small></div></div>{% endfor %}</div>{% endblock %}''')

open('templates/artist.html','w').write('''{% extends 'base.html' %}{% block content %}<div style="padding:30px;background:linear-gradient(#ff000022,#121212);display:flex;gap:20px;align-items:end"><img src="https://via.placeholder.com/180/111/FF0000?text={{artist.name}}" style="border-radius:50%;width:180px;height:180px"><div><p>Artist</p><h1 style="font-size:40px">{{artist.name}}</h1></div></div><div class="section"><h3>Popular</h3>{% for s in songs %}<div class="song-row" onclick="playSong('{{s.file}}','{{s.title}}','{{s.artist}}')"><span style="color:#b3b3b3;width:20px">{{loop.index}}</span><img src="https://via.placeholder.com/100"><div><b>{{s.title}}</b><br><small>{{artist.name}}</small></div></div>{% endfor %}</div>{% endblock %}''')

open('templates/playlist.html','w').write('''{% extends 'base.html' %}{% block content %}<div style="padding:30px;background:linear-gradient(#ff000044,#121212);display:flex;gap:20px;align-items:end"><img src="https://via.placeholder.com/180/FF0000/FFFFFF?text={{playlist.name}}" style="width:180px;height:180px"><div><p>Playlist</p><h1 style="font-size:40px">{{playlist.name}}</h1><p>{{playlist.desc}}</p></div></div><div class="section">{% for s in songs %}<div class="song-row" onclick="playSong('{{s.file}}','{{s.title}}','{{s.artist}}')"><span style="color:#b3b3b3;width:20px">{{loop.index}}</span><img src="https://via.placeholder.com/100"><div><b>{{s.title}}</b><br><small>{{s.artist}}</small></div></div>{% endfor %}</div>{% endblock %}''')

open('templates/upload.html','w').write('''{% extends 'base.html' %}{% block content %}<div class="section" style="max-width:500px;margin:auto;background:#181818;padding:25px;border-radius:10px;border:1px solid #ff0000"><h2 style="color:#ff0000">Upload Wave</h2><br><form method="POST" enctype="multipart/form-data"><input style="width:100%;padding:12px;margin:8px 0;background:#242424;border:none;color:white;border-radius:5px" type="text" name="title" placeholder="Song Title" required><input style="width:100%;padding:12px;margin:8px 0;background:#242424;border:none;color:white;border-radius:5px" type="text" name="artist" placeholder="Artist" required><label>Music file</label><input style="width:100%;padding:12px;margin:8px 0;background:#242424;border:none;color:white;border-radius:5px" type="file" name="music" accept="audio/*"><label>Cover</label><input style="width:100%;padding:12px;margin:8px 0;background:#242424;border:none;color:white;border-radius:5px" type="file" name="cover" accept="image/*"><button class="btn" style="width:100%;margin-top:10px;padding:12px" type="submit">Add To Library</button></form></div>{% endblock %}''')

print("All pages created! Now run python app.py")
